from copy import deepcopy


def attach_ratings(ratings, records, minimum=3.0):
    if not isinstance(ratings, list) or not isinstance(records, list):
        raise TypeError("ratings and records must be lists")
    if isinstance(minimum, bool) or not isinstance(minimum, (int, float)) or not 0 <= minimum <= 5:
        raise ValueError("invalid minimum")

    totals = {}
    for rating in ratings:
        if not isinstance(rating, dict) or set(rating) != {"record_id", "score"}:
            raise ValueError("malformed rating")
        key = rating["record_id"]
        score = rating["score"]
        if not isinstance(key, str) or not key or isinstance(score, bool) or not isinstance(score, (int, float)) or not 0 <= score <= 5:
            raise ValueError("malformed rating")
        total, count = totals.get(key, (0.0, 0))
        totals[key] = (total + score, count + 1)

    result = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError("malformed record")
        key = record.get("record_id")
        if not isinstance(key, str) or not key:
            raise ValueError("malformed record")
        if key in totals:
            total, count = totals[key]
            average = total / count
            if average > minimum:
                copied = deepcopy(record)
                copied["rating_average"] = float(average)
                result.append(copied)
    return result

